// Momora Ambient Sound Engine & White Noise Player
// Desteklenen platformlar: React Native Web, iOS Safari, Android Chrome, Expo

const soundData = {
  "womb": "data:audio/wav;base64,",
  "hairdryer": "data:audio/wav;base64,",
  "rain": "data:audio/wav;base64,",
  "vacuum": "data:audio/wav;base64,",
  "lullaby": "data:audio/wav;base64,",
  "ocean": "data:audio/wav;base64,"
};

let currentAudio = null;
let currentSoundId = null;
let currentVolume = 0.8;
let sleepTimerId = null;
const listeners = new Set();

function notify() {
  listeners.forEach(fn => {
    try { fn({ soundId: currentSoundId, isPlaying: !!currentAudio, volume: currentVolume }); } catch (e) {}
  });
}

export function getSoundUri(id) {
  return soundData[id] || null;
}

export function playSound(id, options = {}) {
  const { volume = currentVolume, timerMinutes = null } = options;
  currentVolume = volume;

  // If already playing this sound, pause it
  if (currentSoundId === id && currentAudio) {
    stopSound();
    return false;
  }

  // Stop previous sound
  if (currentAudio) {
    try {
      currentAudio.pause();
      currentAudio.currentTime = 0;
    } catch (e) {}
    currentAudio = null;
  }

  if (sleepTimerId) {
    clearTimeout(sleepTimerId);
    sleepTimerId = null;
  }

  const uri = soundData[id];
  if (!uri) {
    console.warn('Sound not found:', id);
    return false;
  }

  try {
    if (typeof Audio !== 'undefined') {
      const audio = new Audio(uri);
      audio.loop = true;
      audio.volume = Math.max(0, Math.min(1, currentVolume));
      
      const playPromise = audio.play();
      if (playPromise !== undefined) {
        playPromise.catch(err => {
          console.log('Audio autoplay prevented or error:', err);
        });
      }

      currentAudio = audio;
      currentSoundId = id;

      if (timerMinutes && timerMinutes > 0) {
        sleepTimerId = setTimeout(() => {
          stopSound();
        }, timerMinutes * 60 * 1000);
      }

      notify();
      return true;
    }
  } catch (err) {
    console.warn('Audio playback error:', err);
  }

  currentSoundId = id;
  notify();
  return true;
}

export function stopSound() {
  if (currentAudio) {
    try {
      currentAudio.pause();
      currentAudio.currentTime = 0;
    } catch (e) {}
    currentAudio = null;
  }
  currentSoundId = null;
  if (sleepTimerId) {
    clearTimeout(sleepTimerId);
    sleepTimerId = null;
  }
  notify();
}

export function setVolume(vol) {
  currentVolume = Math.max(0, Math.min(1, vol));
  if (currentAudio) {
    currentAudio.volume = currentVolume;
  }
  notify();
}

export function getCurrentSound() {
  return {
    soundId: currentSoundId,
    isPlaying: !!currentAudio,
    volume: currentVolume,
  };
}

export function addSoundListener(listener) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}
